#include "stdafx.h"#include "8DO.h"K8DO::K8DO(): m_CurParameterID(-1), m_ReadParams( 0 ), firstIndex( 0 ){}static LPCSTR s_MyParameters[]={  "Invert Channel ",  "Failsafe type Channel ",};BOOL K8DO::OnParsingSingleText( std::string &szText, RECTL *rc ){  if( m_CurParameterID!=-1 )  {    CStringA s;    if( !s.IsEmpty() )      m_settings.push_back( s.GetBuffer() );    AddParam( szLast.c_str(), szText.c_str() );    m_CurParameterID = -1;    m_ReadParams++;    return TRUE;//сделать преобразование параметра к виду, пригодному для формирования исполняемого кода  }  for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      m_CurParameterID = i;      int Index = atoi( szText.c_str() + strlen(s_MyParameters[i]) );      if( 0==firstIndex )      {        ASSD( Index > 0 );        firstIndex = Index;      }      char t[64];      sprintf_s( t, "%s%d", s_MyParameters[i], Index - firstIndex + 1 );      szLast = t;      return TRUE;    }  }  return FALSE;}